    /****************************************************************************/

    extern kcom_kernel_t convasm_kernel = {
        .kmem   = cgra_kmem_bitstream,
        .imem   = cgra_imem_bitstream,
        .col_n  = CGRA_N_COLS,
        .in_n   = IN_VAR_DEPTH,
        .out_n  = OUT_VAR_DEPTH,
        .input  = cgra_input,
        .output = cgra_output,
        .config = config,
        .func   = software,
        .check  = check,
        .name   = "Convolution ASM",
    };

    /****************************************************************************/
    /**                                                                        **/
    /*                            LOCAL FUNCTIONS                               */
    /**                                                                        **/
    /****************************************************************************/

    void config()
    {

        for (int j=0; j<3; j++) {
            for (int i=0; i<9; i++) {
                cgra_input[j][i] = in_vector[i];
            }
        }

        cgra_input[3][0] = 9U;

    }

    void software(void)
    {
        conv_check( o_return_soft );
    }

    uint32_t check(void)
    {
        uint32_t errors = 0;

        
        #if PRINT_RESULTS
        PRINTF("\nCGRA\t\tSoft\n");
        #endif
        
        for( int i = 0; i < 7; i++ )
        {
            o_return_cgra = cgra_output[3][i];
            #if PRINT_RESULTS
            PRINTF("%d\t%d\t%s\n",
            o_return_cgra,
            o_return_soft[i],
            (o_return_cgra != o_return_soft[i]) ? "Wrong!\n\n" : "\n\n"
            );
    #endif

            if (o_return_cgra != o_return_soft[i]) {
                errors++;
            }
        }
        return errors;
    }

#endif

